<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useLearning, timeLabel } from '../composables/useLearning'
import { useUserState } from '../composables/useUserState'
import { useResources } from '../composables/useResources'
import { resources } from '../data/resources'
import topics from '../data/topics.json'
import { coverFor } from '../utils/covers'
import LearningRanking from '../components/LearningRanking.vue'
import LearningStudio from '../components/LearningStudio.vue'
import CommunityPoints from '../components/CommunityPoints.vue'
import DifficultyTag from '../components/DifficultyTag.vue'
import {useGrowth} from '../composables/useGrowth'
import {TASK_REWARDS} from '../utils/growth.mjs'
import mascot from '../assets/mascot/jiaxiaozhi.jpg'
const emit=defineEmits<{(e:'back'):void}>()
const {state,today,month,count,consecutive,totalSeconds,checkin,redeem,refresh,open}=useLearning()
const {completed,bookmarks,isCompleted,toggleCompleted}=useUserState()
const {setActive,home}=useResources()
const {growth,points,claim}=useGrowth()
const studio=ref(false)
const tab=ref('签到与奖励'),recordTab=ref('最近学习'),offset=ref(0),toast=ref(''),submission=ref(''),content=ref('')
let timer=0
onMounted(()=>{refresh();timer=window.setInterval(refresh,30000)})
onUnmounted(()=>clearInterval(timer))
const date=computed(()=>{const [y,m]=month.value.split('-').map(Number);return new Date(Date.UTC(y!,m!-1+offset.value,1))})
const displayMonth=computed(()=>date.value.toISOString().slice(0,7))
const calendar=computed(()=>{
  const d=date.value,leading=(d.getUTCDay()+6)%7,length=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()
  return Array.from({length:Math.ceil((leading+length)/7)*7},(_,i)=>{const n=i-leading+1;return n>0&&n<=length?{day:n,key:`${displayMonth.value}-${String(n).padStart(2,'0')}`}:null})
})
const started=computed(()=>resources.filter(r=>(state.courses[r.id]||0)>=3))
const boards=computed(()=>new Set(started.value.map(r=>r.board)))
const hotLearned=computed(()=>started.value.some(r=>topics.some(t=>t.resourceIds.includes(r.id))))
const weekSeconds=computed(()=>{const d=new Date(today.value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return Object.entries(state.seconds).filter(([day])=>day>=d.toISOString().slice(0,10)&&day<=today.value).reduce((a,[,n])=>a+n,0)})
const tasks=computed(()=>[
  {id:'boards',name:'探索四个板块',desc:'在基础、应用、开发、前沿各体验一个合集满3秒。',progress:`${boards.value.size}/4 个板块`,done:boards.value.size>=4,action:'去探索'},
  {id:'minutes3',name:'学习初体验',desc:'先学3分钟，迈出今天的第一步。',progress:`${Math.min(3,Math.floor(totalSeconds.value/60))}/3 分钟`,done:totalSeconds.value>=180,action:'去学习'},
  {id:'minutes10',name:'持续充电',desc:'累计学习10分钟，一点点积累新知识。',progress:`${Math.min(10,Math.floor(totalSeconds.value/60))}/10 分钟`,done:totalSeconds.value>=600,action:'去学习'},
  {id:'hot',name:'追一追热门技术',desc:'体验AI算力工厂或AI办公提效专题中的任意合集满3秒。',progress:hotLearned.value?'1/1 个专题':'0/1 个专题',done:hotLearned.value,action:'看热门'},
  {id:'comment',name:'分享一句学习收获',desc:'围绕一个合集发表有内容的学习评论。',progress:'正式版关联社区评论',done:false,action:'写评论'},
  {id:'feedback',name:'一起建设学习频道',desc:'在体验汇总帖分享使用体验或改进建议。',progress:'正式版关联体验汇总帖',done:false,action:'提建议'},
  {id:'post',name:'发布第一篇学习帖',desc:'分享一个知识点、踩坑经历或应用方法。',progress:'正式版关联社区发帖',done:false,action:'写学习帖'},
  {id:'practice',name:'晒出你的跟练成果',desc:'记录目标、步骤与结果，让同事也能跟着做。',progress:'正式版审核成果',done:false,action:'发跟练帖'},
].map(task=>({...task,points:TASK_REWARDS[task.id]||0})))
const list=computed(()=>recordTab.value==='学过的合集'?resources.filter(r=>completed.has(r.id)):recordTab.value==='我的收藏'?resources.filter(r=>bookmarks.has(r.id)):started.value)
function explore(hot=false){setActive('recommend');home.query='';if(hot)home.topic='ai-dc';emit('back')}
function action(id:string){if(tasks.value.find(t=>t.id===id)?.done){const n=claim(id,tasks.value.filter(t=>t.done).map(t=>t.id));if(n)toast.value=`演示领取成功：${n}积分，未计入真实社区账户。`;return}if(['comment','feedback','post','practice'].includes(id)){submission.value=id;content.value=state.submissions[id]||''}else explore(id==='hot')}
function submit(){if(content.value.trim().length<10)return;state.submissions[submission.value]=content.value.trim();submission.value='';toast.value='演示提交成功，待审核。未发布到真实社区。'}
function reward(tier:number){if(redeem(tier))toast.value=tier===12?'演示领取成功：1500积分，未实际发放。':'演示领取成功：➕啡码1张，未实际发放。'}
</script>
<template>
  <div class="center">
    <button class="back" @click="emit('back')">‹ 返回AI学习频道</button>
    <div class="heading"><div><p class="eyebrow">每一点进步，都值得记录</p><h1>我的学习</h1></div><span class="demo-tag">本地演示 · 奖励不实际发放</span></div>
    <div class="stats"><div><strong>{{ timeLabel(state.seconds[today]||0) }}</strong><span>今日学习</span></div><div><strong>{{ timeLabel(weekSeconds) }}</strong><span>本周学习</span></div><div><strong>{{ timeLabel(totalSeconds) }}</strong><span>累计学习</span></div><div><strong>{{ completed.size }}<small> 个</small></strong><span>学过的合集</span></div></div>
    <nav class="tabs" aria-label="我的学习页签"><button v-for="name in ['签到与奖励','成长任务','学习排行榜','学习记录','学习宠物']" :key="name" :class="{selected:tab===name&&!studio}" @click="tab=name;studio=false">{{ name }}</button></nav>
    <p v-if="toast" class="notice" role="status">{{ toast }} <button @click="toast=''" aria-label="关闭提示">×</button></p>
    <LearningStudio v-if="studio" mode="print" @close="studio=false" />
    <LearningStudio v-else-if="tab==='学习宠物'" mode="pet" @close="tab='成长任务'" />
    <template v-else-if="tab==='签到与奖励'">
      <div class="check-layout"><section class="panel calendar">
        <div class="section-head"><h2>{{ displayMonth.replace('-','年') }}月签到日历</h2><div class="month-controls"><button @click="offset--" aria-label="上个月">‹</button><button :disabled="offset>=0" @click="offset++" aria-label="下个月">›</button><button v-if="offset" @click="offset=0">本月</button></div></div>
        <p class="muted">当前连续签到 <b>{{ consecutive }}</b> 天，本月累计 <b>{{ count }}</b> 天</p>
        <div class="calendar-grid"><span v-for="w in ['一','二','三','四','五','六','日']" :key="w" class="weekday">{{ w }}</span><template v-for="(cell,i) in calendar" :key="i"><button v-if="cell" class="day" :class="{signed:state.days.includes(cell.key),today:cell.key===today}" :disabled="cell.key!==today||state.days.includes(cell.key)" :aria-label="`${cell.key}${state.days.includes(cell.key)?' 已签到':cell.key===today?' 点击签到':''}`" @click="checkin"><span>{{ cell.day }}</span><b v-if="state.days.includes(cell.key)">✓</b><small v-else-if="cell.key===today">今日</small></button><span v-else></span></template></div>
        <div class="calendar-footer"><span>✓ 已签到　○ 今日</span><button class="primary" :disabled="state.days.includes(today)" @click="checkin">{{ state.days.includes(today)?'✓ 今日已签到':'今日签到' }}</button></div><p class="muted rule">北京时间每日一次。手动签到或站内模拟播放满3秒均可，当天不重复累计。</p>
      </section><aside class="panel rewards"><h2>本月坚持奖励</h2><p class="muted">累计签到，漏签不清零。每月重新累计。</p>
        <div class="reward-timeline"><div class="track"><span :style="{width:Math.min(count/21,1)*100+'%'}"></span></div><span class="start-node">0天</span><div v-for="tier in [12,21]" :key="tier" class="timeline-node" :class="{reached:count>=tier}" :style="{left:tier/21*100+'%'}"><span class="node-dot">{{ count>=tier?'✓':'' }}</span><b>{{ tier }}天</b><button :disabled="count<tier||state.claims.includes(month+':'+tier)" @click="reward(tier)">{{ state.claims.includes(month+':'+tier)?'已领取':'领取奖励' }}</button></div></div>
        <p class="milestone">本月已签到 {{ count }} 天</p><div v-for="tier in [12,21]" :key="tier" class="reward"><span class="reward-icon">{{ tier===12?'✦':'☕' }}</span><div><b>{{ tier===12?'1500积分':'➕啡码 × 1' }}</b><p>{{ tier===12?'本月累计签到12天':'本月累计签到21天 · 价值3000积分' }}</p></div><button :disabled="count<tier||state.claims.includes(month+':'+tier)" @click="reward(tier)">{{ state.claims.includes(month+':'+tier)?'已领取':count>=tier?'领取奖励':`还差${tier-count}天` }}</button></div><p class="muted rule">两档可分别领取，每月各一次。➕啡码不额外扣除积分。此处为演示兑换，实际规则与发放需接入社区。</p><button class="text-link" @click="tab='成长任务'">去完成成长任务 ›</button><button class="text-link" @click="tab='学习排行榜'">查看学习排行榜 ›</button></aside></div>
      <section class="panel next"><div><h2>今天，学会一点新东西</h2><p class="muted">去逛逛AI算力工厂与办公提效，或分享你的第一条学习心得。</p></div><button @click="explore(true)">去热门专题 ›</button></section>
    </template>
    <section v-else-if="tab==='成长任务'" class="panel tasks">
      <div class="section-head"><h2>从学习者，到分享者</h2><span class="points-total">已演示领取 {{ points }} 积分</span></div>
      <p class="muted">完成任务领50—300积分 · 每项限领一次 · 新增奖励拟定，是否与社区原积分叠加待运营确认。</p>
      <div class="growth-perks"><article><span class="perk-icon">✧</span><div><h3>定制3D打印手办</h3><p>月榜前10名奖励 · 获奖后解锁半定制</p></div><button @click="studio=true">3D打印屋 ›</button></article><article><img :src="mascot" alt="稼小智基础款"/><div><h3>稼小智学习宠物</h3><p>领养一个安静陪你学习的小伙伴</p></div><button @click="tab='学习宠物'">{{ growth.pet.claimed?'管理宠物':'去领取' }} ›</button></article></div>
      <CommunityPoints />
      <div class="section-head"><h3>我的成长任务</h3><span class="muted">{{ tasks.filter(t=>t.done).length }}/{{ tasks.length }} 项已完成</span></div>
      <article v-for="(task,i) in tasks" :key="task.id" class="task"><span class="task-icon">{{ String(i+1).padStart(2,'0') }}</span><div class="task-copy"><h3>{{ task.name }} <span class="task-points">+{{ task.points }}积分</span></h3><p>{{ task.desc }}</p><small>{{ growth.taskClaims.includes(task.id)?'已演示领取 · 不重复发放':state.submissions[task.id]?'已演示提交 · 待审核':task.progress }}</small></div><button :class="{primary:task.done&&!growth.taskClaims.includes(task.id)}" :disabled="growth.taskClaims.includes(task.id)" @click="action(task.id)">{{ growth.taskClaims.includes(task.id)?'✓ 已领取':task.done?`领取${task.points}积分`:state.submissions[task.id]?'查看提交':task.action }}</button></article>
      <p class="muted rule">学习类任务按本机演示记录判断，互动类任务须关联个人账号并审核后发奖；匿名内容不计。真实社区积分每天凌晨自动更新，严禁自动刷积分。本Demo不实际发放积分。</p>
    </section>
    <LearningRanking v-else-if="tab==='学习排行榜'" @print="studio=true" />
<section v-else class="panel"><div class="section-head"><h2>我的学习足迹</h2><span class="muted">演示时长，仅保存在当前浏览器</span></div><nav class="record-tabs"><button v-for="name in ['最近学习','学过的合集','我的收藏']" :key="name" :class="{selected:recordTab===name}" @click="recordTab=name">{{ name }}</button></nav><p v-if="!list.length" class="empty">这里还没有记录，选一个喜欢的合集开始吧。<button @click="explore()">去学习</button></p><article v-for="r in list" :key="r.id" class="record"><img :src="coverFor(r)" alt=""/><div><h3>{{ r.title }} <DifficultyTag :difficulty="r.difficulty" :reason="r.difficultyReason" /></h3><p>{{ timeLabel(state.courses[r.id]||0) }}演示学习 · {{ isCompleted(r.id)?'手动标记学过':'尚未标记学过' }}</p></div><div class="record-actions"><button @click="open(r)">继续学习</button><button @click="toggleCompleted(r.id)">{{ isCompleted(r.id)?'取消学过':'标记学过' }}</button></div></article></section>
    <div v-if="submission" class="scrim" @click.self="submission=''"><section class="submission" role="dialog" aria-modal="true" aria-label="成长任务演示提交"><h2>{{ tasks.find(t=>t.id===submission)?.name }}</h2><p class="muted">本地演示，不会发布到真实社区，提交后等待审核。</p><label for="task-content">学习内容、收获或建议（至少10字）</label><textarea id="task-content" v-model="content" rows="6" maxlength="3000"></textarea><div class="submit-actions"><button @click="submission=''">取消</button><button class="primary" :disabled="content.trim().length<10" @click="submit">提交演示内容</button></div></section></div>
  </div>
</template>
<style scoped>
.points-total{font-size:13px;color:var(--accent-ink);font-weight:600}.task-points{display:inline-block;color:var(--accent-ink);font-size:12px;background:var(--surface-2);border:1px solid var(--accent-line);border-radius:16px;padding:3px 9px;margin-left:8px;white-space:nowrap}.growth-perks{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:22px 0}.growth-perks article{display:flex;align-items:center;gap:12px;background:var(--surface-2);border:1px solid var(--border);border-radius:14px;padding:18px}.growth-perks article>div{flex:1}.growth-perks p{font-size:11px;line-height:1.7;color:var(--muted);margin:6px 0 0}.growth-perks img{width:60px;height:60px;object-fit:contain;border-radius:13px;background:white}.perk-icon{display:grid;place-items:center;width:60px;height:60px;font-size:32px;color:var(--accent-ink);border:1px solid var(--accent-line);border-radius:13px}.growth-perks button{white-space:nowrap;padding:8px 10px}.growth-perks h3{font-size:14px}@media(max-width:900px){.growth-perks{grid-template-columns:1fr}}@media(max-width:620px){.task-points{margin:6px 0 0;display:table}.growth-perks article{padding:12px;gap:10px}.growth-perks img,.perk-icon{width:44px;height:44px}.task button{font-size:11px;padding:8px}}
.reward-timeline{position:relative;margin:35px 38px 10px 8px;height:108px}.reward-timeline .track{margin-top:0;position:absolute;top:6px;left:0;right:0}.timeline-node{position:absolute;top:0;transform:translateX(-50%);display:flex;align-items:center;flex-direction:column;gap:8px;white-space:nowrap}.node-dot{height:18px;width:18px;border-radius:50%;background:var(--surface-3);border:2px solid var(--border);box-sizing:border-box;font-size:11px;text-align:center}.timeline-node b{font-size:12px;color:var(--muted)}.timeline-node button{font-size:11px;padding:6px 8px}.timeline-node.reached .node-dot{background:#52bba4;color:white;border-color:#52bba4}.timeline-node.reached b{color:var(--accent-ink)}.start-node{position:absolute;left:0;top:28px;color:var(--muted);font-size:12px}.tabs{overflow-x:auto}.tabs button{white-space:nowrap;flex:none}
.center{max-width:1120px;margin:0 auto;padding:8px 0 48px;color:var(--ink)}button{cursor:pointer;font:inherit;color:var(--ink);border:1px solid var(--border);background:var(--surface-2);border-radius:9px;padding:9px 15px;font-size:13px}button:disabled{cursor:default;opacity:.55}.back,.text-link{border:0;background:none;color:var(--accent-ink);padding-left:0}.heading,.section-head,.calendar-footer,.next,.task,.record,.submit-actions{display:flex;align-items:center;justify-content:space-between;gap:18px}.heading{margin:20px 0 25px}h1{font-size:30px;margin:6px 0}h2{font-size:19px;margin:0}h3{font-size:15px;margin:0 0 6px}.eyebrow,.muted{font-size:13px;color:var(--muted);line-height:1.7}.eyebrow{margin:0}.demo-tag{font-size:12px;color:var(--accent-ink);background:var(--surface-2);border:1px solid var(--border);padding:8px 12px;border-radius:20px}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--border);border-radius:14px;background:var(--surface);padding:22px 0}.stats>div{padding:0 25px;border-right:1px solid var(--border)}.stats>div:last-child{border:0}.stats strong{display:block;font-size:25px;color:var(--ink)}.stats span{display:block;font-size:12px;color:var(--muted);margin-top:8px}.stats small{font-size:14px;font-weight:400}.tabs{display:flex;gap:26px;margin:26px 0 22px;border-bottom:1px solid var(--border)}.tabs button{border:0;background:none;border-radius:0;padding:12px 0;font-size:15px}.tabs .selected{color:var(--accent-ink);border-bottom:3px solid var(--accent);font-weight:700}.panel{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:25px}.check-layout{display:grid;grid-template-columns:1.45fr 1fr;gap:20px}.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:7px;margin-top:20px}.weekday{text-align:center;padding:4px 0 10px;font-size:12px;color:var(--muted)}.day{height:55px;padding:7px;display:flex;align-items:center;justify-content:center;gap:5px;background:var(--surface-2);border-color:transparent}.day:disabled{opacity:1;color:var(--muted)}.day.today{border-color:var(--accent);color:var(--accent-ink)}.day.signed{background:#dcf7ec;color:#16866b}.day small{font-size:10px}.calendar-footer{margin-top:20px;font-size:12px;color:var(--muted)}.primary{background:var(--accent);border-color:var(--accent);color:white}.rule{font-size:11px;margin-top:18px}.month-controls{display:flex;gap:5px}.month-controls button{padding:4px 9px}.track{height:7px;background:var(--surface-3);border-radius:5px;margin-top:28px;overflow:hidden}.track span{display:block;height:100%;background:#52bba4}.milestone{font-size:12px;text-align:right;color:var(--muted)}.reward{display:flex;align-items:center;gap:12px;padding:22px 0;border-bottom:1px solid var(--border)}.reward-icon{font-size:25px;color:var(--accent-ink)}.reward>div{flex:1}.reward b{font-size:19px}.reward p{font-size:11px;line-height:1.6;color:var(--muted);margin:8px 0 0}.reward button{white-space:nowrap;padding:8px 10px;font-size:12px}.next{margin-top:20px}.next p{margin-bottom:0}.task{padding:22px 0;border-bottom:1px solid var(--border)}.task:last-child{border:0}.task-icon{background:var(--surface-2);color:var(--accent-ink);padding:13px;border-radius:50%;font-size:13px}.task-copy{flex:1}.task-copy p{font-size:13px;color:var(--muted);margin:0 0 7px}.task-copy small{font-size:11px;color:var(--accent-ink)}.task button{flex:none}.record-tabs{display:flex;gap:8px;margin:24px 0}.record-tabs .selected{color:var(--accent-ink);border-color:var(--accent-line)}.record{padding:18px 0;border-bottom:1px solid var(--border)}.record img{width:145px;aspect-ratio:16/9;object-fit:cover;border-radius:8px}.record>div:nth-child(2){flex:1}.record p{font-size:12px;color:var(--muted)}.record-actions{display:flex;gap:8px}.empty{padding:40px;text-align:center;color:var(--muted);font-size:14px}.empty button{display:block;margin:20px auto}.notice{background:var(--surface-2);padding:12px 16px;border-radius:8px;color:var(--accent-ink);font-size:13px}.notice button{float:right;border:0;padding:0;background:none}.scrim{position:fixed;inset:0;z-index:90;display:grid;place-items:center;background:#10162788;padding:20px}.submission{background:var(--surface);width:min(600px,100%);padding:28px;border-radius:18px}.submission label{display:block;font-size:13px;margin:16px 0 8px}.submission textarea{width:100%;border:1px solid var(--border);border-radius:9px;background:var(--surface-2);color:var(--ink);padding:12px;box-sizing:border-box;font:inherit}.submit-actions{justify-content:flex-end;margin-top:18px}
@media(max-width:720px){.heading{align-items:flex-start;flex-direction:column;gap:10px}.stats{grid-template-columns:repeat(2,1fr);gap:22px}.stats>div:nth-child(2){border:0}.check-layout{grid-template-columns:1fr}.panel{padding:18px}.day{height:44px;padding:3px;gap:2px}.section-head{gap:8px}.section-head h2{font-size:16px}.section-head>span{font-size:11px}.task{gap:10px}.task-icon{display:none}.record{flex-wrap:wrap;gap:10px}.record img{width:100px}.record-actions{width:100%;justify-content:flex-end}.record h3{font-size:13px}.next{align-items:flex-start}.next h2{font-size:16px}.next button{flex:none;padding:8px}.tabs{gap:24px}.stats strong{font-size:22px}}
</style>
